typedef struct {
  int h, w;
} Person;

static int cmp(const void *a, const void *b) {
  Person *x = (Person *)a, *y = (Person *)b;
  if (x->h != y->h) return x->h - y->h;
  return y->w - x->w;
}

int bestSeqAtIndex(int *height, int heightSize, int *weight, int weightSize) {
  (void)weightSize;
  Person *people = (Person *)malloc(sizeof(Person) * heightSize);
  for (int i = 0; i < heightSize; i++) {
    people[i].h = height[i];
    people[i].w = weight[i];
  }
  qsort(people, heightSize, sizeof(Person), cmp);
  int *dp = (int *)malloc(sizeof(int) * heightSize);
  int len = 0;
  for (int i = 0; i < heightSize; i++) {
    int lo = 0, hi = len;
    while (lo < hi) {
      int mid = lo + (hi - lo) / 2;
      if (dp[mid] < people[i].w) {
        lo = mid + 1;
      } else {
        hi = mid;
      }
    }
    dp[lo] = people[i].w;
    if (lo == len) len++;
  }
  free(people);
  free(dp);
  return len;
}

class Solution {
public:
  int bestSeqAtIndex(vector<int> &height, vector<int> &weight) {
    vector<pair<int, int>> people;
    for (size_t i = 0; i < height.size(); i++) people.push_back({height[i], weight[i]});
    sort(people.begin(), people.end(), [](const pair<int, int> &a, const pair<int, int> &b) {
      if (a.first != b.first) return a.first < b.first;
      return a.second > b.second;
    });
    vector<int> dp;
    for (auto &p : people) {
      auto it = lower_bound(dp.begin(), dp.end(), p.second);
      if (it == dp.end()) dp.push_back(p.second);
      else *it = p.second;
    }
    return dp.size();
  }
};

func bestSeqAtIndex(height []int, weight []int) int {
	people := make([][2]int, len(height))
	for i := range height {
		people[i] = [2]int{height[i], weight[i]}
	}
	sort.Slice(people, func(i, j int) bool {
		if people[i][0] != people[j][0] {
			return people[i][0] < people[j][0]
		}
		return people[i][1] > people[j][1]
	})
	dp := []int{}
	for _, p := range people {
		w := p[1]
		lo, hi := 0, len(dp)
		for lo < hi {
			mid := lo + (hi-lo)/2
			if dp[mid] < w {
				lo = mid + 1
			} else {
				hi = mid
			}
		}
		if lo == len(dp) {
			dp = append(dp, w)
		} else {
			dp[lo] = w
		}
	}
	return len(dp)
}

class Solution {
  public int bestSeqAtIndex(int[] height, int[] weight) {
    int n = height.length;
    int[][] people = new int[n][2];
    for (int i = 0; i < n; i++) {
      people[i][0] = height[i];
      people[i][1] = weight[i];
    }
    Arrays.sort(people, (a, b) -> a[0] != b[0] ? a[0] - b[0] : b[1] - a[1]);
    List<Integer> dp = new ArrayList<>();
    for (int[] p : people) {
      int w = p[1];
      int lo = 0, hi = dp.size();
      while (lo < hi) {
        int mid = lo + (hi - lo) / 2;
        if (dp.get(mid) < w) lo = mid + 1;
        else hi = mid;
      }
      if (lo == dp.size()) dp.add(w);
      else dp.set(lo, w);
    }
    return dp.size();
  }
}

class Solution:
    def bestSeqAtIndex(self, height: List[int], weight: List[int]) -> int:
        people = sorted(zip(height, weight), key=lambda p: (p[0], -p[1]))
        dp = []
        for _, w in people:
            idx = bisect_left(dp, w)
            if idx == len(dp):
                dp.append(w)
            else:
                dp[idx] = w
        return len(dp)

impl Solution {
  pub fn best_seq_at_index(height: Vec<i32>, weight: Vec<i32>) -> i32 {
    let mut people: Vec<(i32, i32)> = height.iter().cloned().zip(weight.iter().cloned()).collect();
    people.sort_by(|a, b| if a.0 != b.0 { a.0.cmp(&b.0) } else { b.1.cmp(&a.1) });
    let mut dp: Vec<i32> = vec![];
    for (_, w) in people {
      let idx = dp.partition_point(|&x| x < w);
      if idx == dp.len() {
        dp.push(w);
      } else {
        dp[idx] = w;
      }
    }
    dp.len() as i32
  }
}

const bestSeqAtIndex = (height: number[], weight: number[]): number => {
  const people: number[][] = height.map((h, i) => [h, weight[i]]);
  people.sort((a, b) => (a[0] !== b[0] ? a[0] - b[0] : b[1] - a[1]));
  const dp: number[] = [];
  for (const [, w] of people) {
    let lo = 0;
    let hi = dp.length;
    while (lo < hi) {
      const mid = lo + Math.floor((hi - lo) / 2);
      if (dp[mid] < w) lo = mid + 1;
      else hi = mid;
    }
    if (lo === dp.length) dp.push(w);
    else dp[lo] = w;
  }
  return dp.length;
};
